#!/usr/bin/env python3
from pathlib import Path
import base64, gzip

PAYLOAD = """"""

content = gzip.decompress(base64.b64decode(PAYLOAD)).decode("utf-8")
assert "<h3>Find pilot</h3>" in content
assert "SNAPSHOT_URL" in content
assert "loadPilotSnapshot();" in content
Path("index.html").write_text(content, encoding="utf-8")
print("Applied Sky Finder v1.1 index payload")
